/**
 * OWNED INSTRUMENTATION (arrival-common-manual, added after reference-1).
 *
 * reference-1 measured a contradiction that is a defect in THIS HARNESS, not a
 * game claim: the three ordinary clicks were dispatched at the centre of a
 * canvas rectangle sampled BEFORE the loop, and the browser reported their
 * event target as a <p>; meanwhile document.elementFromPoint, recomputed LIVE
 * from the canvas rect at each poll, reported the canvas at its own point. A
 * click aimed at a stale rectangle can therefore land somewhere that is not the
 * canvas, and CameraControls only locks for a click whose target IS the canvas.
 *
 * This rule is pure and gates only the HARNESS's aim: it refuses to click a
 * canvas rectangle that is not a plausible live viewport-sized canvas, and
 * returns the exact intended point so it can be recorded and re-measured. It
 * changes no game predicate, no geometry, no acceptance and no gate.
 */
export function clickPointFromRect(rect, viewport = null) {
  const bad = (why) => ({ ok: false, why, x: null, y: null, rect: rect ?? null });
  if (!rect || typeof rect !== 'object') return bad('canvas rect unavailable');
  const { x, y, width, height } = rect;
  for (const [k, v] of [['x', x], ['y', y], ['width', width], ['height', height]]) {
    if (!Number.isFinite(v)) return bad(`canvas rect ${k} is not finite (${String(v)})`);
  }
  if (width < 200 || height < 200) {
    return bad(`canvas rect is ${width}x${height}: too small to be the live world canvas (an unsized/default rect aims the click off-canvas)`);
  }
  if (viewport && Number.isFinite(viewport.width) && Number.isFinite(viewport.height)) {
    if (width < viewport.width * 0.5 || height < viewport.height * 0.5) {
      return bad(`canvas rect ${width}x${height} covers less than half the ${viewport.width}x${viewport.height} viewport`);
    }
  }
  const px = Math.round(x + width / 2);
  const py = Math.round(y + height / 2);
  if (viewport && Number.isFinite(viewport.width) && Number.isFinite(viewport.height)
    && (px < 0 || py < 0 || px > viewport.width || py > viewport.height)) {
    return bad(`intended point ${px},${py} is outside the ${viewport.width}x${viewport.height} viewport`);
  }
  return { ok: true, why: null, x: px, y: py, rect: { x, y, width, height } };
}
EOF
