const STAND_CANDIDATES = [
  { name: 'W', point: [CG_POSES.W.x, CG_POSES.W.y, CG_POSES.W.z], authored: true },
  { name: 'E.z-3', point: [CG_POSES.E.x, CG_POSES.E.y, CG_POSES.E.z - 3], authored: false },
